import { useState, useRef, useEffect } from "react";
import { Link2, Twitter, Linkedin, Check, ScanLine } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { getScoreHex, getScoreLabel } from "@/lib/score-utils";

interface ShareScoreModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  score: number;
  url: string;
  reportUrl?: string;
}

export function ShareScoreModal({
  open,
  onOpenChange,
  score,
  url,
  reportUrl,
}: ShareScoreModalProps) {
  const [linkCopied, setLinkCopied] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);

  const scoreColor = getScoreHex(score);
  const scoreLabel = getScoreLabel(score);
  const shareUrl = reportUrl ?? window.location.href;

  let hostname = url;
  try { hostname = new URL(url).hostname.replace("www.", ""); } catch { /* keep raw */ }

  // Circumference math for the ring
  const size = 120;
  const strokeWidth = 10;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference * (1 - score / 100);

  const handleCopyLink = async () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    try {
      await navigator.clipboard.writeText(shareUrl);
    } catch {
      const textarea = document.createElement("textarea");
      textarea.value = shareUrl;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
    }
    setLinkCopied(true);
    toast.success("Report link copied to clipboard!");
    timerRef.current = setTimeout(() => setLinkCopied(false), 2500);
  };

  const handleTwitter = () => {
    const text = encodeURIComponent(
      `I just audited ${hostname} with @ConvertScan and got a CRO score of ${score}/100.\n\nFind out your conversion score — it's free:`
    );
    const encodedUrl = encodeURIComponent(shareUrl);
    window.open(
      `https://twitter.com/intent/tweet?text=${text}&url=${encodedUrl}`,
      "_blank",
      "noopener,noreferrer"
    );
  };

  const handleLinkedIn = () => {
    const encodedUrl = encodeURIComponent(shareUrl);
    window.open(
      `https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}`,
      "_blank",
      "noopener,noreferrer"
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm gap-0 p-0 overflow-hidden">
        <DialogHeader className="sr-only">
          <DialogTitle>Share your CRO score</DialogTitle>
        </DialogHeader>

        {/* Score card preview — dark branded */}
        <div className="bg-[#0F172A] px-8 py-10 text-center">
          {/* Logo */}
          <div className="mb-6 flex items-center justify-center gap-2">
            <div className="flex h-6 w-6 items-center justify-center rounded-md bg-indigo-500">
              <ScanLine className="h-3 w-3 text-white" />
            </div>
