import { Link } from "react-router-dom";
import { Lock, ScanLine } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { CRO_PILLARS } from "@/lib/constants";
import { cn } from "@/lib/utils";

const PILLAR_LABELS: Record<string, string> = {
  value_proposition: "Value Proposition",
  cta_effectiveness: "CTA Effectiveness",
  trust_signals: "Trust Signals",
  visual_hierarchy: "Visual Hierarchy",
  mobile_experience: "Mobile Experience",
  content_copy: "Content & Copy",
  page_performance: "Page Performance",
};

interface ScanGateWallProps {
  teaserScore: number;
  url: string;
}

export function ScanGateWall({ teaserScore, url }: ScanGateWallProps) {
  const signupHref = `/signup?redirect=/scan&url=${encodeURIComponent(url)}`;

  let hostname = url;
  try { hostname = new URL(url).hostname.replace("www.", ""); } catch { /* keep raw */ }

  // Fake pillar scores for the blurred preview — same seed every render for consistency
  const fakePillarScores = [38, 61, 44, 72, 53, 48, 67];

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div className="text-center">
        <h2 className="text-xl font-semibold tracking-tight text-foreground">
          Your CRO audit is ready
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          We found conversion issues on{" "}
          <span className="font-medium text-foreground">{hostname}</span>
        </p>
      </div>

      <Card className="border-border/50 shadow-soft overflow-hidden">
        <CardContent className="p-0">
          {/* Score preview */}
          <div className="bg-gradient-to-br from-slate-50 to-white p-8 text-center border-b border-border/40">
            <p className="mb-4 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
              Your CRO Score
            </p>
            <ScoreRing score={teaserScore} size={140} strokeWidth={10} />
            <p className="mt-4 text-sm text-muted-foreground">
              Your page is in the bottom{" "}
              <span className="font-semibold text-foreground">{100 - teaserScore}%</span> for
              conversion rate optimization.
            </p>
          </div>

          {/* Blurred pillar breakdown */}
          <div className="relative p-6">
            <div className="space-y-3 blur-sm select-none pointer-events-none" aria-hidden="true">
              {CRO_PILLARS.map((pillar, i) => {
                const fakeScore = fakePillarScores[i] ?? 50;
                const barColor =
                  fakeScore >= 70
                    ? "bg-green-500"
                    : fakeScore >= 40
                    ? "bg-amber-500"
                    : "bg-red-500";
                return (
                  <div key={pillar.key} className="flex items-center gap-3">
                    <span className="w-36 shrink-0 truncate text-xs text-foreground/80">
                      {PILLAR_LABELS[pillar.key]}
                    </span>
                    <div className="relative h-2 flex-1 overflow-hidden rounded-full bg-muted/50">
                      <div
                        className={cn("h-full rounded-full", barColor)}
                        style={{ width: `${fakeScore}%` }}
                      />
                    </div>
                    <span className="w-8 text-right text-xs font-semibold tabular-nums text-foreground">
                      {fakeScore}
                    </span>
                  </div>
                );
              })}
            </div>

            {/* Lock overlay */}
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-white/60 backdrop-blur-sm">
              <div className="rounded-2xl border border-border/50 bg-white p-6 text-center shadow-lg max-w-xs">
                <div className="mx-auto mb-3 flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-50">
                  <Lock className="h-5 w-5 text-indigo-600" />
                </div>
                <h3 className="text-base font-semibold text-foreground">
                  Unlock your full CRO audit report
                </h3>
                <p className="mt-2 text-xs text-muted-foreground leading-relaxed">
                  See all 23 issues found, AI rewrite suggestions, and exact steps to fix each problem.
                </p>
                <Button asChild className="mt-4 w-full rounded-lg bg-indigo-600 text-white hover:bg-indigo-700">
                  <Link to={signupHref}>
                    <ScanLine className="mr-2 h-4 w-4" />
                    Create Free Account
                  </Link>
                </Button>
                <p className="mt-2 text-xs text-muted-foreground">
                  Already have an account?{" "}
                  <Link to="/login" className="font-medium text-indigo-600 hover:underline">
                    Log in
                  </Link>
                </p>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

